import os
from flask import Flask, session

app = Flask(__name__)
app.config.update(
    SECRET_KEY=os.environ.get("FLASK_SECRET_KEY", "local-only-not-for-production"),
    SESSION_COOKIE_HTTPONLY=True,
    SESSION_COOKIE_SAMESITE="Lax",
)

@app.post("/preferences")
def preferences():
    session["theme"] = "dark"
    return {"saved": True}
